  List<LightLayer> LiveLayers {get {if(DS.MemoryMode)return tab.Contains("风扇")?DS.HardwareFanLayers:DS.HardwareLayers;return tab.Contains("风扇")?DS.FanLayers:DS.Layers;}}
  void StartAnimation(){if(animationTimer!=null)return;animationTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(33)};animationTimer.Tick+=delegate{if(WindowState==WindowState.Minimized)return;double t=(DateTime.Now-animationStart).TotalSeconds;foreach(var a in animations.ToArray())a(t);};animationTimer.Start();Closed+=delegate{animationTimer.Stop();};}
  static Color Hue(double h){h=(h%1+1)%1*6;int k=(int)h;double f=h-k;byte q=(byte)(255*(1-f)),t=(byte)(255*f);switch(k){case 0:return Color.FromRgb(255,t,0);case 1:return Color.FromRgb(q,255,0);case 2:return Color.FromRgb(0,255,t);case 3:return Color.FromRgb(0,q,255);case 4:return Color.FromRgb(t,0,255);default:return Color.FromRgb(255,0,q);}}
  FrameworkElement EffectIcon(int index,string color){string[] paths={"M12,2 L12,22 M3,7 L21,17 M3,17 L21,7 M9,3 L12,6 15,3 M9,21 L12,18 15,21","M2,20 L6,3 10,20 14,3 18,20 22,3","M9,9 C2,9 2,18 9,18 L14,18 M15,14 C22,14 22,5 15,5 L10,5 M8,12 L16,12","M12,5 C3,0 1,12 8,12 C2,21 15,24 16,16 C23,18 27,5 18,7 C18,0 9,0 12,5","M3,20 C3,1 9,1 9,20 M12,20 C12,1 18,1 18,20","M12,21 L3,11 C-3,1 10,0 12,7 C15,0 27,1 21,11 Z","M12,3 A3,3 0 1 0 12,9 A3,3 0 1 0 12,3 M4,11 A3,3 0 1 0 4,17 A3,3 0 1 0 4,11 M20,11 A3,3 0 1 0 20,17 A3,3 0 1 0 20,11 M12,18 A3,3 0 1 0 12,24 A3,3 0 1 0 12,18","M5,2 C-3,11 13,11 5,2 M16,8 C6,21 27,21 16,8","M2,12 A10,10 0 1 0 22,12 A10,10 0 1 0 2,12 M6,12 A6,6 0 1 0 18,12 A6,6 0 1 0 6,12","M2,19 A10,12 0 0 1 22,19 M6,19 A6,8 0 0 1 18,19 M10,19 A2,4 0 0 1 14,19","M12,2 L12,6 M12,18 L12,22 M2,12 L6,12 M18,12 L22,12 M4,4 L7,7 M17,17 L20,20 M4,20 L7,17 M17,7 L20,4","M3,5 L8,5 8,10 13,10 13,15 18,15 18,20 23,20","M4,4 L20,4 20,20 4,20 Z","M10,4 A2,2 0 0 1 14,4 L14,15 A4,4 0 1 1 10,15 Z","M3,20 L20,3 M3,15 L3,20 8,20"};return new System.Windows.Shapes.Path{Data=Geometry.Parse(paths[index%paths.Length]),Stroke=B(color),StrokeThickness=1.8,Width=20,Height=20,Stretch=Stretch.Uniform,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round};}
  static Color EffectColor(LightLayer l,int i,int count,double time){double t=time*(.15+l.Speed/40),v=1;Color c;try{c=(Color)ColorConverter.ConvertFromString(l.Color);}catch{c=Colors.DeepSkyBlue;}string e=l.Effect;if(e.Contains("彩虹")||e=="水彩光谱"||e=="色彩轮盘"||e=="颜色变化")c=Hue(t*.12+(e=="颜色变化"?0:(double)i/count));else if(e=="下雨")v=Math.Pow(Math.Max(0,Math.Sin(i*2.31-t*3)),8);else if(e=="彩色脉冲")v=(Math.Sin(t*2)+1)/2;else if(e=="心跳")v=Math.Pow(Math.Max(0,Math.Sin(t*4)),4);else if(e=="闪烁")v=Math.Sin(t*9+i*13)>0?1:0;else if(e=="顺序"||e=="跑马灯"||e=="色波")v=Math.Pow((Math.Sin(t*3-i*.65)+1)/2,3);else if(e=="温度")c=Color.FromRgb(220,130,25);if(l.RandomColor)c=Hue(i*.13+t*.08);else if(l.Effect!="静态颜色"&&Math.Sin(t)>0){try{c=(Color)ColorConverter.ConvertFromString(l.Color2);}catch{}}return Color.FromRgb((byte)(c.R*v),(byte)(c.G*v),(byte)(c.B*v));}
  void Led(Canvas parent,double x,double y,double size,int id,int count){var state=DS;var layers=LiveLayers;var dot=new Ellipse{StrokeThickness=1,Cursor=Cursors.Hand,ToolTip="LED "+(id+1)};Put(parent,dot,x,y,size,size);Action<double> draw=t=>{Color col=Color.FromRgb(100,100,100);foreach(var l in layers)if(tab!="屏幕设置"&&l.Enabled&&(l.Zones.Count==0||l.Zones.Contains(id)))col=EffectColor(l,id,count,t);if(col.R+col.G+col.B<15)col=Color.FromRgb(115,115,115);double b=state.Brightness/100;dot.Fill=new SolidColorBrush(Color.FromRgb((byte)(col.R*b),(byte)(col.G*b),(byte)(col.B*b)));bool selected=editing&&activeLayer>=0&&activeLayer<layers.Count&&(layers[activeLayer].Zones.Count==0||layers[activeLayer].Zones.Contains(id));dot.Stroke=B(selected?"#FFFFFF":"#333333");};draw(0);animations.Add(draw);dot.MouseLeftButtonDown+=(s,e)=>{if(!editing||activeLayer<0||activeLayer>=layers.Count)return;var zones=layers[activeLayer].Zones;bool multi=(Keyboard.Modifiers&ModifierKeys.Control)!=0;if(!multi){zones.Clear();zones.Add(id);}else {if(zones.Count==0)zones.AddRange(Enumerable.Range(0,count));if(!zones.Remove(id))zones.Add(id);}Save();e.Handled=true;};}
  void AdvancedDeviceVisual(bool ring){if(!device.StartsWith("H100")){MemorySchematic();return;}if(tab.Contains("风扇")){for(int fan=0;fan<3;fan++){double x=380+fan*168;var card=Pane(surface,x,224,152,176,tileBg);Pane(card,0,0,152,24,railBg,0);Label(card,"RGB端口 #"+(fan==0?1:fan==1?5:6),8,0,140,24,13);Fan(card,20,44,112);for(int i=0;i<8;i++){double a=i*Math.PI/4;Led(card,69+25.76*Math.Sin(a),93+25.76*Math.Cos(a),9,fan*8+i,24);}}return;}PumpBody();DrawLcd();if(ring)for(int i=0;i<24;i++){double a=(i+DS.Rotation/15)*Math.PI/12;Led(surface,866+91*Math.Sin(a),305-91*Math.Cos(a),14,i,24);}}
  void LayerMenu(Canvas parent,int index){var layer=LiveLayers[index];Menu(parent,0,0,new[]{"重命名","复制","上移","下移",layer.Enabled?"禁用":"启用","删除"},n=>{if(n==0){RenameText(layer.Name,v=>{layer.Name=v;Save();Build();});return;}if(n==1)LiveLayers.Insert(index+1,new LightLayer{Name=layer.Name+" 副本",Color=layer.Color,Effect=layer.Effect,Speed=layer.Speed,Enabled=layer.Enabled,RandomColor=layer.RandomColor,Color2=layer.Color2,Zones=new List<int>(layer.Zones)});if(n==2&&index>0){LiveLayers.RemoveAt(index);LiveLayers.Insert(index-1,layer);activeLayer=index-1;}if(n==3&&index<LiveLayers.Count-1){LiveLayers.RemoveAt(index);LiveLayers.Insert(index+1,layer);activeLayer=index+1;}if(n==4)layer.Enabled=!layer.Enabled;if(n==5){LiveLayers.RemoveAt(index);editing=false;activeLayer=-1;}Save();Build();});}
  void ZoneDialog(){if(activeLayer<0||activeLayer>=LiveLayers.Count)return;var layer=LiveLayers[activeLayer];var draft=new List<int>(layer.Zones);var p=Modal("快捷灯光效果区域",560,320);Label(p,"选择灯珠",24,56,480,24,15);for(int i=0;i<24;i++){int id=i;var b=Click(p,(i+1).ToString(),24+i%8*62,96+i/8*44,54,34,()=>{},draft.Count==0||draft.Contains(i)?selectedBg:tileBg);b.Click+=delegate{if(draft.Count==0)draft.AddRange(Enumerable.Range(0,24));if(!draft.Remove(id))draft.Add(id);b.Background=B(draft.Contains(id)?selectedBg:tileBg);};}Click(p,"应用",284,268,116,28,()=>{layer.Zones=draft;Save();Build();},"#EEE915","#111111");Click(p,"取消",412,268,124,28,CloseModal,selectedBg);}
  CurveState CurrentCurve(){var list=DS.Curves;var c=list.Find(x=>x.Name==selectedCooling);if(c==null){c=new CurveState{Name=selectedCooling,Values=new List<double>{10,30,50,70,90}};list.Add(c);}if(c.Temperatures.Count!=c.Values.Count)c.Temperatures=Enumerable.Range(0,c.Values.Count).Select(i=>20d+i*10).ToList();return c;}
