  bool SpecialScreen(){if(DS.ScreenType=="图像/GIF"&&File.Exists(DS.ImagePath)){try{BitmapDecoder decoder;using(var f=File.OpenRead(DS.ImagePath))decoder=BitmapDecoder.Create(f,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);var image=new Image{Source=decoder.Frames[0],Stretch=Stretch.UniformToFill,Clip=new EllipseGeometry(new Point(75,75),75,75),Opacity=DS.LcdBrightness/100};Put(surface,image,798,237,150,150);var state=DS;animations.Add(t=>{image.Source=decoder.Frames[(int)(t*Math.Max(1,state.Fps))%decoder.Frames.Count];image.Opacity=state.LcdBrightness/100;});return true;}catch{}}
