  void VerifyAdvanced(List<string> log,Action<string> capture){device="H100i ELITE LCD";page="设备";tab="环";DS.MemoryMode=false;activeLayer=0;editing=true;LiveLayers[0].Zones=new List<int>{1,4,8};LiveLayers[0].Speed=73;tab="8-LED风扇系列";if(LiveLayers.Count!=1||LiveLayers[0].Zones.Count!=0)throw new Exception("通道未隔离");DS.MemoryMode=true;LiveLayers.Add(new LightLayer{Effect="静态颜色",Color="#FF0088"});if(DS.HardwareLayers.Count!=0||DS.HardwareFanLayers.Count!=1)throw new Exception("硬件模式未隔离");DS.MemoryMode=false;selectedCooling="自定义 1";CurrentCurve().Values[2]=63;Save();var reloaded=Read(Store).Profiles[0].Cooler;if(reloaded.Layers[0].Zones.Count!=3||reloaded.Layers[0].Speed!=73||reloaded.HardwareFanLayers[0].Color!="#FF0088"||reloaded.Curves[0].Values[2]!=63)throw new Exception("编辑状态持久化失败");log.Add("Independent ring / fan / memory-mode layers, LED selection, speed and curve persistence: OK");var animated=new LightLayer{Effect="彩虹波浪"};if(EffectColor(animated,0,24,0)==EffectColor(animated,0,24,1))throw new Exception("动画未变化");var solid=new LightLayer{Effect="静态颜色",Color="#FF0088",RandomColor=false};if(EffectColor(solid,0,24,0)!=EffectColor(solid,0,24,9))throw new Exception("静态效果未固定");log.Add("Animated and static effect sampling: OK");Pref.Theme="深色";Build();foreach(var a in animations.ToArray())a(1.25);capture("深色-风扇动态灯效");tab="散热";coolingEdit=true;Build();capture("深色-曲线编辑");VerifyCoolingHistory(log,capture);}
